import{_ as a,o,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"الگ تھلگ جگہ کم آلودگی کا عمل","description":"","frontmatter":{},"headers":[],"relativePath":"ur/86-隔离空间低污染流程.md","filePath":"ur/86-隔离空间低污染流程.md","lastUpdated":1789183869000}'),e={name:"ur/86-隔离空间低污染流程.md"};function l(i,t,n,h,s,u){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="الگ-تھلگ-جگہ-کم-آلودگی-کا-عمل" tabindex="-1">الگ تھلگ جگہ کم آلودگی کا عمل <a class="header-anchor" href="#الگ-تھلگ-جگہ-کم-آلودگی-کا-عمل" aria-label="Permalink to &quot;الگ تھلگ جگہ کم آلودگی کا عمل&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>86</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>الگ تھلگ جگہ، کم آلودگی، قانونی رکاوٹ، پاکیزگی کا طریقہ کار، آلودگی کی نگرانی</td></tr></tbody></table><h2 id="_1-الگ-تھلگ-جگہ-کی-تعریف-اور-افعال" tabindex="-1">1. الگ تھلگ جگہ کی تعریف اور افعال <a class="header-anchor" href="#_1-الگ-تھلگ-جگہ-کی-تعریف-اور-افعال" aria-label="Permalink to &quot;1. الگ تھلگ جگہ کی تعریف اور افعال&quot;">​</a></h2><p>الگ تھلگ جگہ جگہ کے قانونی ضابطے کی ٹیکنالوجی کے ذریعے قانونی نیٹ ورک میں بنایا گیا ایک خودمختار بند علاقہ ہے، جو کاپی آئینہ دور دراز آثار قدیمہ اسکیم کا بنیادی کام کی جگہ ہے۔ الگ تھلگ جگہ اور بیرونی کائنات کے درمیان مکمل قانونی رکاوٹ سے مکمل طور پر الگ کیا گیا ہے، اندر خودمختار قانونی پیرامیٹرز کا نظام اور توانائی کے چکر کا نظام موجود ہے۔ اس کا بنیادی کام آثار قدیمہ کی کاپی کے لیے ایک مستحکم، قابل کنٹرول، ہدف سے مکمل طور پر الگ تھلگ تحقیقی ماحول فراہم کرنا ہے، ساتھ ہی اس بات کو یقینی بنانا ہے کہ آثار قدیمہ کے عمل میں پیدا ہونے والی تمام آلودگی سختی سے الگ تھلگ جگہ کے اندر محدود رہے، اپنی سطح یا ہدف سطح پر باہر نہ نکلیں۔</p><p>الگ تھلگ جگہ کی تعمیر جگہ قانونی ضابطے کے نظام کے چوتھے مرحلے (فا کونگ جِنگ) کی قانونی آپریشن کی صلاحیت پر مبنی ہے۔ تعمیر کرنے والے کو قانونی نیٹ ورک میں ایک &quot;قانونی خالی علاقہ&quot; منتخب کرنا ہوتا ہے — یعنی ایسا علاقہ جہاں موجودہ قانونی پیرامیٹرز نسبتاً یکساں ہوں، کوئی سطحی ڈھانچہ نہ ہو، پھر جگہ کے قانونی آپریشن کے ذریعے اس علاقے میں ایک کروی یا مکعبی شکل کی بند جگہ بنانا، اور اس کے لیے خودمختار قانونی پیرامیٹرز مقرر کرنا۔ الگ تھلگ جگہ کا سائز ضرورت کے مطابق ایڈجسٹ کیا جا سکتا ہے، معمول کے آثار قدیمہ کے لیے الگ تھلگ جگہ کا حجم عام طور پر 1000 سے 100000 مکعب میٹر کے درمیان ہوتا ہے۔</p><p>الگ تھلگ جگہ ایک بار استعمال ہونے والی اشیاء نہیں ہے، بلکہ دوبارہ استعمال ہونے والی بنیادی ڈھانچہ ہے۔ ہینگ یوان ژو نے اہم اینکروں کے قریب معیاری &quot;الگ تھلگ جگہ گروپ&quot; قائم کیا ہے، تاکہ آثار قدیمہ کی ٹیمیں ضرورت کے مطابق کرایہ پر لے سکیں۔ ہر آثار قدیمہ کے کام کے ختم ہونے کے بعد، الگ تھلگ جگہ مکمل پاکیزگی اور دوبارہ ترتیب دینے کے بعد، اگلے استعمال میں لگائی جا سکتی ہے۔</p><h2 id="_2-کم-آلودگی-کے-عمل-کا-عمومی-فریم-ورک" tabindex="-1">2. کم آلودگی کے عمل کا عمومی فریم ورک <a class="header-anchor" href="#_2-کم-آلودگی-کے-عمل-کا-عمومی-فریم-ورک" aria-label="Permalink to &quot;2. کم آلودگی کے عمل کا عمومی فریم ورک&quot;">​</a></h2><p>الگ تھلگ جگہ کم آلودگی کا عمل آثار قدیمہ کے پورے عمل میں پھیلا ہوا ایک آلودگی سے بچاؤ کا نظام ہے، جس کا عمومی فریم ورک &quot;پہلے بچاؤ، درمیان میں نگرانی، بعد میں پاکیزگی&quot; تین مراحل میں تقسیم ہے، ہر مرحلے میں واضح آپریشن کے اصول اور معیار کے معیارات ہیں۔ کم آلودگی کے عمل کا مقصد یہ ہے کہ آثار قدیمہ کے آپریشن کے بیرونی ماحول (اپنی سطح اور ہدف سطح سمیت) پر آلودگی کے اثرات کو &quot;قانونی طور پر نظر انداز کیے جانے کے قابل سطح&quot; تک کم کیا جائے — یعنی آلودگی کی مقدار قانونی نیٹ ورک کی قدرتی اتار چڑھاؤ کی مقدار سے کم ہو، کسی بھی سطح کے قانونی نگرانی کے نظام سے محسوس نہ کی جا سکے۔</p><h3 id="_2-1-پہلے-بچاؤ-کا-مرحلہ" tabindex="-1">2.1 پہلے بچاؤ کا مرحلہ <a class="header-anchor" href="#_2-1-پہلے-بچاؤ-کا-مرحلہ" aria-label="Permalink to &quot;2.1 پہلے بچاؤ کا مرحلہ&quot;">​</a></h3><p>پہلے بچاؤ آثار قدیمہ کے کام کے باضابطہ آغاز سے پہلے کیا جاتا ہے، بنیادی طور پر درج ذیل کام شامل ہیں:</p><ol><li><p><strong>الگ تھلگ جگہ کا انتخاب اور کسٹمائزیشن</strong>: آثار قدیمہ کے ہدف کی قانونی خصوصیات کے مطابق، متعلقہ قانونی پیرامیٹرز والی الگ تھلگ جگہ منتخب یا کسٹمائز کریں۔ الگ تھلگ جگہ کے اندر قانونی پیرامیٹرز جتنا ممکن ہو ہدف سطح کے ماحولیاتی پیرامیٹرز کے قریب ہونے چاہییں، تاکہ کاپی کے استحکام کو یقینی بنایا جا سکے، ساتھ ہی اپنی سطح کے قانونی پیرامیٹرز سے کافی فرق برقرار رکھنا چاہیے، تاکہ کاپی کے مادے اور اپنی سطح کے قانون کے درمیان منفی ردعمل پیدا نہ ہو۔</p></li><li><p><strong>رکاوٹ کی طاقت کا معائنہ</strong>: الگ تھلگ جگہ کی قانونی رکاوٹ کا مکمل معائنہ کریں، اس بات کو یقینی بنائیں کہ رکاوٹ کی سالمیت اور طاقت معیار پر پہنچ گئی ہے۔ رکاوٹ کی طاقت کو &quot;قانونی دخول گتانک&quot; سے ماپا جاتا ہے، معیار کا مطالبہ ہے کہ دخول گتانک 10 کی منفی 15 گھات سے کم ہو — یعنی فی سیکنڈ رکاوٹ سے گزرنے والی قانونی معلومات کی مقدار 10 کی منفی 15 گھات بٹ سے زیادہ نہ ہو۔ معائنے میں نااہل الگ تھلگ جگہ کو استعمال میں نہیں لایا جا سکتا۔</p></li><li><p><strong>افراد کی پاکیزگی</strong>: الگ تھلگ جگہ میں داخل ہونے والے تمام آثار قدیمہ کے اہلکاروں کو داخلے سے پہلے &quot;تین سطحی پاکیزگی کا طریقہ کار&quot; (حیاتیاتی پاکیزگی، توانائی کی پاکیزگی، شعور کی پاکیزگی) مکمل کرنا ضروری ہے، تفصیل کے لیے دستاویز 81 &quot;سطح گزر کے اصول&quot; دیکھیں۔ پاکیزگی مکمل ہونے کے بعد، افراد کو معیاری &quot;قانونی الگ تھلگ لباس&quot; پہننا ہوگا، یہ لباس افراد کے جسم کے اندر کی توانائی اور شعور کے اتار چڑھاؤ کو باہر نکلنے سے مزید روک سکتا ہے۔</p></li><li><p><strong>آلات کی پاکیزگی</strong>: الگ تھلگ جگہ میں لے جانے والے تمام آلات اور اوزار بھی پاکیزگی کے عمل سے گزرنے چاہییں، اس بات کو یقینی بنانا کہ آلات کی سطح اور اندر اپنی سطح کے جرثوموں، توانائی کی باقیات اور معلومات کے ٹکڑوں کو نہیں لے جاتے۔ آلات کی پاکیزگی &quot;قانونی اسکین ہٹانے کا طریقہ&quot; استعمال کرتی ہے، ہائی فریکوئنسی قانونی اسکین کے ذریعے آلات پر موجود تمام غیر ملکی باقیات کو الگ کر دیتی ہے۔</p></li></ol><h3 id="_2-2-درمیان-میں-نگرانی-کا-مرحلہ" tabindex="-1">2.2 درمیان میں نگرانی کا مرحلہ <a class="header-anchor" href="#_2-2-درمیان-میں-نگرانی-کا-مرحلہ" aria-label="Permalink to &quot;2.2 درمیان میں نگرانی کا مرحلہ&quot;">​</a></h3><p>آثار قدیمہ کے آپریشن کے دوران، کم آلودگی کے عمل کا بنیادی فوکس ریئل ٹائم نگرانی اور فوری ردعمل ہے۔ الگ تھلگ جگہ میں ہر طرف سے آلودگی کی نگرانی کا نظام نصب ہے، جس میں شامل ہیں:</p><table tabindex="0"><thead><tr><th>نگرانی کی قسم</th><th>نگرانی کا مواد</th><th>الرام کی حد</th><th>ردعمل کا طریقہ کار</th></tr></thead><tbody><tr><td>حیاتیاتی آلودگی کی نگرانی</td><td>الگ تھلگ جگہ میں کاپی کے ماخوذ کے علاوہ کوئی جرثومہ موجود ہے یا نہیں</td><td>1 غیر ملکی جرثومہ دریافت</td><td>فوری طور پر مقامی جراثیم کشی شروع کریں، افراد کی پاکیزگی کے ریکارڈ کی جانچ کریں</td></tr><tr><td>توانائی کی آلودگی کی نگرانی</td><td>الگ تھلگ جگہ کے توانائی کے میدان میں غیر معمولی اتار چڑھاؤ ہے یا نہیں</td><td>اتار چڑھاؤ کی حد بنیادی قدر کے 0.01% سے زیادہ</td><td>آثار قدیمہ کے آپریشن روکیں، اتار چڑھاؤ کے منبع کو تلاش کریں اور ختم کریں</td></tr><tr><td>شعور کی آلودگی کی نگرانی</td><td>الگ تھلگ جگہ کے شعور کے دائرے میں غیر ملکی خیال کا سگنل ہے یا نہیں</td><td>سگنل کی طاقت 10 کی منفی 8 گھات شعور اکائی سے زیادہ</td><td>شعور کی روک تھام کا میدان شروع کریں، افراد کی شعور کی حالت کی جانچ کریں</td></tr><tr><td>رکاوٹ کی سالمیت کی نگرانی</td><td>قانونی رکاوٹ میں دراڑ یا کمزور نقطہ ہے یا نہیں</td><td>دخول گتانک 10 کی منفی 12 گھات سے زیادہ</td><td>فوری طور پر رکاوٹ کی مرمت کا طریقہ کار شروع کریں، ضرورت پڑنے پر ہنگامی انخلاء کریں</td></tr></tbody></table><p>نگرانی کے نظام کی نگرانی خودمختار &quot;آلودگی نگران&quot; کرتا ہے، نگران مخصوص آثار قدیمہ کے آپریشن میں حصہ نہیں لیتا، خاص طور پر آلودگی کی نگرانی اور ہنگامی ردعمل کے لیے ذمہ دار ہے۔ ایک بار جب آلودگی حد سے تجاوز کر گئی معلوم ہو جائے، نگران کے پاس فوری طور پر تمام آثار قدیمہ کے آپریشن روکنے اور متعلقہ ہنگامی طریقہ کار شروع کرنے کا حق ہے۔</p><h3 id="_2-3-بعد-میں-پاکیزگی-کا-مرحلہ" tabindex="-1">2.3 بعد میں پاکیزگی کا مرحلہ <a class="header-anchor" href="#_2-3-بعد-میں-پاکیزگی-کا-مرحلہ" aria-label="Permalink to &quot;2.3 بعد میں پاکیزگی کا مرحلہ&quot;">​</a></h3><p>آثار قدیمہ کے کام کے ختم ہونے کے بعد، ضروری ہے کہ الگ تھلگ جگہ کی مکمل پاکیزگی اور دوبارہ ترتیب دی جائے، اس بات کو یقینی بنانا کہ الگ تھلگ جگہ میں کوئی کاپی مادہ، توانائی کی باقیات یا معلومات کے ٹکڑے باقی نہ رہیں۔ بعد میں پاکیزگی چار مراحل میں تقسیم ہے:</p><ol><li><p><strong>کاپی کی تباہی</strong>: الگ تھلگ جگہ کے تمام کاپی مادے کو &quot;قانونی فنا کا طریقہ کار&quot; کے ذریعے مکمل طور پر تباہ کریں۔ قانونی فنا کا طریقہ کار کاپی مادے کے ذرہ کے ڈھانچے کو مکمل طور پر توڑ کر بنیادی توانائی بنا دیتا ہے، پھر توانائی کو الگ تھلگ جگہ کے توانائی کے چکر کے نظام میں لے جایا جاتا ہے غیر جانبدار کرنے کے لیے۔ تباہی کے عمل میں یقینی بنانا ضروری ہے کہ مادے کی فنا کی شرح 100% تک پہنچ جائے، کوئی ذرہ باقی رہنے کی اجازت نہیں ہے۔</p></li><li><p><strong>توانائی کی غیر جانبداری</strong>: الگ تھلگ جگہ کے توانائی کے میدان کی مکمل غیر جانبداری کریں، آثار قدیمہ کے عمل میں پیدا ہونے والی تمام غیر معمولی توانائی کے اتار چڑھاؤ کو ختم کریں، توانائی کے میدان کو الگ تھلگ جگہ کی بنیادی حالت میں واپس لائیں۔ توانائی کی غیر جانبداری &quot;الٹی لہر روکنے کا طریقہ&quot; استعمال کرتی ہے، غیر معمولی اتار چڑھاؤ کے مرحلے کے مخالف توانائی کی لہر پیدا کرنے کے ذریعے درست روک تھام حاصل کی جاتی ہے۔</p></li><li><p><strong>معلومات کا خاتمہ</strong>: الگ تھلگ جگہ کے شعور کے دائرے اور معلومات کی پرت کی گہری صفائی کریں، آثار قدیمہ کے عمل میں پیدا ہونے والی تمام معلومات کی باقیات کو ختم کریں۔ معلومات کا خاتمہ &quot;قانونی دوبارہ لکھنے کا طریقہ&quot; استعمال کرتا ہے، بے ترتیب شور کی معلومات سے اصل معلومات کی باقیات کو ڈھانپ دیتا ہے، پھر شور کی معلومات کو ختم کر دیتا ہے، اس بات کو یقینی بناتا ہے کہ ختم کردہ معلومات کو کسی بھی تکنیکی ذریعے سے بحال نہیں کیا جا سکتا۔</p></li><li><p><strong>جگہ کی دوبارہ ترتیب</strong>: اوپر تین مراحل مکمل ہونے کے بعد، الگ تھلگ جگہ کی مجموعی قانونی دوبارہ ترتیب کریں، اندرونی قانونی پیرامیٹرز کو فیکٹری معیاری حالت میں واپس لائیں۔ دوبارہ ترتیب دینے کے بعد، الگ تھلگ جگہ نئے دور کے رکاوٹ کے معائنے اور آلودگی کے معائنے سے گزرتی ہے، اہلیت کی تصدیق کے بعد ہی ذخیرہ میں رکھی جا سکتی ہے۔</p></li></ol><h2 id="_3-آلودگی-کے-حادثے-کی-درجہ-بندی-اور-نمٹنا" tabindex="-1">3. آلودگی کے حادثے کی درجہ بندی اور نمٹنا <a class="header-anchor" href="#_3-آلودگی-کے-حادثے-کی-درجہ-بندی-اور-نمٹنا" aria-label="Permalink to &quot;3. آلودگی کے حادثے کی درجہ بندی اور نمٹنا&quot;">​</a></h2><p>سخت کم آلودگی کے عمل کے باوجود، آلودگی کے حادثے کے امکان کو مکمل طور پر مسترد نہیں کیا جا سکتا۔ ہینگ یوان ژو الگ تھلگ جگہ کے آلودگی کے حادثے کو تین درجوں میں تقسیم کرتا ہے:</p><ul><li><p><strong>پہلا درجہ کا حادثہ (ہلکی آلودگی)</strong>: تھوڑی مقدار میں آلودگی پیدا کرنے والا مادہ یا توانائی الگ تھلگ جگہ کے اندر محدود ہے، قانونی رکاوٹ کو توڑا نہیں ہے۔ نمٹنے کا طریقہ: الگ تھلگ جگہ میں مقامی پاکیزگی کریں، بیرونی ماحول کو متاثر نہیں کرتا، بعد میں حادثہ رپورٹ جمع کروانا ہی کافی ہے۔</p></li><li><p><strong>دوسرا درجہ کا حادثہ (رکاوٹ ٹوٹنا)</strong>: آلودگی نے قانونی رکاوٹ کو توڑ دیا ہے، لیکن آلودگی کی مقدار کم ہے اور بروقت دریافت ہو گئی ہے، اپنی سطح کے قانونی نیٹ ورک میں پھیل نہیں سکی۔ نمٹنے کا طریقہ: فوری طور پر رکاوٹ کی مرمت اور بیرونی پاکیزگی کا طریقہ کار شروع کریں، آلودگی نگران کو سطح انتظامیہ بیورو کو تفصیلی حادثہ رپورٹ جمع کروانا ضروری ہے، متعلقہ افراد تفتیش کا شکار ہوتے ہیں۔</p></li><li><p><strong>تیسرا درجہ کا حادثہ (شدید پھیلاؤ)</strong>: آلودگی بڑے پیمانے پر اپنی سطح کے قانونی نیٹ ورک میں پھیل گئی ہے، اپنی سطح کی قانونی استحکام یا ماحولیاتی ماحول کو متاثر کر سکتی ہے۔ نمٹنے کا طریقہ: فوری طور پر اعلیٰ ترین سطح کا ہنگامی ردعمل شروع کریں، اینکر کونسل براہ راست آلودگی کے خاتمے اور وجوہاتی مرمت کے کام کی ہدایت کریں گی، متعلقہ ذمہ دار افراد قانونی سزا کا سامنا کریں گے۔</p></li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>الگ تھلگ جگہ کم آلودگی کا عمل ایک مکمل آلودگی سے بچاؤ کا نظام ہے جس میں &quot;بچاؤ بنیادی، نگرانی معاون، پاکیزگی حتمی ضمانت&quot; ہے۔ یہ پہلے سخت بچاؤ، درمیان میں ریئل ٹائم نگرانی اور بعد میں مکمل پاکیزگی کے ذریعے، آثار قدیمہ کے آپریشن کے آلودگی کے خطرے کو کم سے کم کرتا ہے۔ یہ عمل اینکر سمبیوسس تہذیب کی کائناتی ماحول کے لیے ذمہ داری کے احساس کو ظاہر کرتا ہے — یہاں تک کہ علم کی تلاش کے عمل میں بھی، کبھی بھی دوسری جگہ کو آلودہ کرنے کی قیمت پر کام نہیں کرتا۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>84-آثار قدیمہ پروٹوکول کا عمومی خاکہ</li><li>85-کاپی آئینہ دور دراز آثار قدیمہ اسکیم</li><li>64-الگ تھلگ جگہ کی تعمیر کی ٹیکنالوجی</li></ul>',25)])])}const _=a(e,[["render",l]]);export{q as __pageData,_ as default};
